pragma solidity 0.8.28;

import { AccessControl } from "@openzeppelin/contracts/access/AccessControl.sol";
import { ReentrancyGuard } from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import { Pausable } from "@openzeppelin/contracts/utils/Pausable.sol";
import { SafeERC20, IERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { IERC20Permit } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";
import { SharedErrors } from "./SharedErrors.sol";
import { ISpinEconomy } from "./interfaces/ISpinEconomy.sol";
import { IRewardTreasury } from "./interfaces/IRewardTreasury.sol";

/// @title SpinEconomy
/// @notice Contract-only entry fees and item purchases; splits to treasury + SpinPrizeVault.
/// @dev ERC20 users can call *WithPermit (OpenZeppelin IERC20Permit / EIP-2612) for a single tx.
contract SpinEconomy is ISpinEconomy, AccessControl, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    address public immutable nativeAsset;
    address public treasury;
    address public prizeVault;
    uint16 public treasuryBps; // e.g. 7000 = 70%

    mapping(address => bool) public assetEnabled;
    mapping(address => uint8) public assetDecimals;
    address[] public assetList;

    modifier onlyEnabledAsset(address asset) {
        if (!assetEnabled[asset]) revert SharedErrors.AssetDisabled();
        _;
    }

    constructor(address _nativeAsset, address _treasury, address _prizeVault, uint16 _treasuryBps) {
        if (_treasury == address(0) || _prizeVault == address(0)) revert SharedErrors.InvalidAddress();
        if (_treasuryBps > 10_000) revert SharedErrors.InvalidInput();

        nativeAsset = _nativeAsset;
        treasury = _treasury;
        prizeVault = _prizeVault;
        treasuryBps = _treasuryBps;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(PAUSER_ROLE, msg.sender);

        assetEnabled[_nativeAsset] = true;
        assetDecimals[_nativeAsset] = 18;
        assetList.push(_nativeAsset);
    }

    function enableAsset(address asset, uint8 decimals_) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (asset == address(0)) revert SharedErrors.InvalidAddress();
        if (assetEnabled[asset]) revert SharedErrors.AssetAlreadyExists();
        assetEnabled[asset] = true;
        assetDecimals[asset] = decimals_;
        assetList.push(asset);
    }

    function setTreasuryBps(uint16 bps) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (bps > 10_000) revert SharedErrors.InvalidInput();
        treasuryBps = bps;
        emit SplitUpdated(bps);
    }

    function setTreasury(address t) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (t == address(0)) revert SharedErrors.InvalidAddress();
        treasury = t;
        emit TreasuryUpdated(t);
    }

    function setPrizeVault(address v) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (v == address(0)) revert SharedErrors.InvalidAddress();
        prizeVault = v;
        emit VaultUpdated(v);
    }

    function payEntry(address asset, uint256 amount, bytes32 sessionRef)
        external
        payable
        whenNotPaused
        nonReentrant
        onlyEnabledAsset(asset)
    {
        amount = _intake(asset, amount);
        (uint256 toTreasury, uint256 toVault) = _split(amount);
        _forward(asset, toTreasury, toVault);
        emit EntryPaid(msg.sender, asset, amount, toTreasury, toVault, sessionRef);
    }

    function purchaseItem(bytes32 itemId, address asset, uint256 amount)
        external
        payable
        whenNotPaused
        nonReentrant
        onlyEnabledAsset(asset)
    {
        if (itemId == bytes32(0)) revert SharedErrors.InvalidInput();
        amount = _intake(asset, amount);
        (uint256 toTreasury, uint256 toVault) = _split(amount);
        _forward(asset, toTreasury, toVault);
        emit ItemPurchased(msg.sender, itemId, asset, amount, toTreasury, toVault);
    }

    /// @inheritdoc ISpinEconomy
    function payEntryWithPermit(
        address asset,
        uint256 amount,
        bytes32 sessionRef,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external whenNotPaused nonReentrant onlyEnabledAsset(asset) {
        if (asset == nativeAsset) revert SharedErrors.InvalidInput();
        if (amount == 0) revert SharedErrors.InvalidAmount();
        _permit(asset, amount, deadline, v, r, s);
        amount = _intake(asset, amount);
        (uint256 toTreasury, uint256 toVault) = _split(amount);
        _forward(asset, toTreasury, toVault);
        emit EntryPaid(msg.sender, asset, amount, toTreasury, toVault, sessionRef);
    }

    /// @inheritdoc ISpinEconomy
    function purchaseItemWithPermit(
        bytes32 itemId,
        address asset,
        uint256 amount,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external whenNotPaused nonReentrant onlyEnabledAsset(asset) {
        if (itemId == bytes32(0)) revert SharedErrors.InvalidInput();
        if (asset == nativeAsset) revert SharedErrors.InvalidInput();
        if (amount == 0) revert SharedErrors.InvalidAmount();
        _permit(asset, amount, deadline, v, r, s);
        amount = _intake(asset, amount);
        (uint256 toTreasury, uint256 toVault) = _split(amount);
        _forward(asset, toTreasury, toVault);
        emit ItemPurchased(msg.sender, itemId, asset, amount, toTreasury, toVault);
    }

    function _permit(address asset, uint256 amount, uint256 deadline, uint8 v, bytes32 r, bytes32 s) private {
        IERC20Permit(asset).permit(msg.sender, address(this), amount, deadline, v, r, s);
    }

    function _intake(address asset, uint256 amount) private returns (uint256) {
        if (asset == nativeAsset) {
            if (msg.value == 0) revert SharedErrors.InvalidAmount();
            return msg.value;
        }
        if (amount == 0) revert SharedErrors.InvalidAmount();
        if (msg.value != 0) revert SharedErrors.InvalidInput();
        IERC20(asset).safeTransferFrom(msg.sender, address(this), amount);
        return amount;
    }

    function _split(uint256 amount) private view returns (uint256 toTreasury, uint256 toVault) {
        toTreasury = (amount * treasuryBps) / 10_000;
        toVault = amount - toTreasury;
    }

    function _forward(address asset, uint256 toTreasury, uint256 toVault) private {
        if (asset == nativeAsset) {
            if (toTreasury > 0) {
                IRewardTreasury(treasury).deposit{ value: toTreasury }();
            }
            if (toVault > 0) {
                (bool ok,) = prizeVault.call{ value: toVault }("");
                if (!ok) revert SharedErrors.TransferFailed();
            }
        } else {
            if (toTreasury > 0) {
                IERC20(asset).forceApprove(treasury, toTreasury);
                IRewardTreasury(treasury).depositERC20(asset, toTreasury);
            }
            if (toVault > 0) {
                IERC20(asset).safeTransfer(prizeVault, toVault);
            }
        }
    }

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }
}
","keccak256":"0xd4221221620a363167a49955889a03088717eae736d40cacd3a5eb8788f1553a","license":"MIT"},"contracts/interfaces/IRewardTreasury.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

/// @title IRewardTreasury
/// @notice Interface for the RewardTreasury contract
interface IRewardTreasury {
    /// @notice Asset information stored in the registry
    struct AssetInfo {
        address assetAddress;
        string symbol;
        uint8 decimals;
        bool enabled;
    }

    /// @notice Per-asset accounting statistics
    struct AssetStatistics {
        uint256 totalDeposited;
        uint256 totalPaid;
        uint256 balance;
    }

    /// @notice Overall treasury statistics
    struct TreasuryStatistics {
        uint256 totalDeposits;
        uint256 totalRewards;
        uint256 totalWithdrawals;
        uint256 rewardCount;
        uint256 largestReward;
    }

    /// @notice Deposits native asset into the treasury
    function deposit() external payable;

    /// @notice Deposits ERC20 asset into the treasury
    /// @param asset The ERC20 token address
    /// @param amount The amount to deposit
    function depositERC20(address asset, uint256 amount) external;

    /// @notice Withdraws assets from the treasury
    /// @param asset The asset address to withdraw
    /// @param to The recipient address
    /// @param amount The amount to withdraw
    function withdraw(address asset, address to, uint256 amount) external;

    /// @notice Executes a reward payout to a recipient
    /// @param recipient The reward recipient
    /// @param asset The asset to pay out
    /// @param amount The payout amount
    /// @param requestId Unique request ID for replay protection
    function payout(address recipient, address asset, uint256 amount, bytes32 requestId) external;

    /// @notice Returns the total native asset balance held by the treasury
    function treasuryBalance() external view returns (uint256);

    /// @notice Returns the balance of a specific asset held by the treasury
    /// @param asset The asset address
    function assetBalance(address asset) external view returns (uint256);

    /// @notice Checks if an asset is supported
    /// @param asset The asset address
    function isSupportedAsset(address asset) external view returns (bool);

    /// @notice Returns all supported assets
    function getSupportedAssets() external view returns (AssetInfo[] memory);

    /// @notice Enables a new asset for deposits and payouts
    /// @param asset The ERC20 asset address
    /// @param symbol The asset symbol
    /// @param decimals The asset decimals
    function enableAsset(address asset, string calldata symbol, uint8 decimals) external;

    /// @notice Disables an asset
    /// @param asset The asset address to disable
    function disableAsset(address asset) external;

    /// @notice Returns statistics for a specific asset
    /// @param asset The asset address
    function assetStatistics(address asset) external view returns (AssetStatistics memory);

    /// @notice Returns overall treasury statistics
    function treasuryStatistics() external view returns (TreasuryStatistics memory);
}
","keccak256":"0x2782cbbe04a02f8852ceb9872e09e6c1c68345d03a63c9b4343c704c07e37dee","license":"MIT"},"contracts/interfaces/ISpinEconomy.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

interface ISpinEconomy {
    event EntryPaid(
        address indexed user,
        address indexed asset,
        uint256 amount,
        uint256 treasuryShare,
        uint256 vaultShare,
        bytes32 indexed sessionRef
    );

    event ItemPurchased(
        address indexed user,
        bytes32 indexed itemId,
        address indexed asset,
        uint256 amount,
        uint256 treasuryShare,
        uint256 vaultShare
    );

    event SplitUpdated(uint16 treasuryBps);
    event TreasuryUpdated(address treasury);
    event VaultUpdated(address vault);

    function payEntry(address asset, uint256 amount, bytes32 sessionRef) external payable;

    function purchaseItem(bytes32 itemId, address asset, uint256 amount) external payable;

    /// @notice EIP-2612: signature + pull in one user transaction (no prior approve tx).
    function payEntryWithPermit(
        address asset,
        uint256 amount,
        bytes32 sessionRef,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external;

    /// @notice EIP-2612: signature + pull in one user transaction (no prior approve tx).
    function purchaseItemWithPermit(
        bytes32 itemId,
        address asset,
        uint256 amount,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external;

    function treasuryBps() external view returns (uint16);
}
